command:
$ErrorActionPreference = "Stop"
git fetch origin main work/content-search --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch failed" }
if ((git rev-parse origin/main).Trim() -ne "28b60642923cf3280f04b43c2322f50eea3b07b1") { throw "main moved" }
if ((git rev-parse origin/work/content-search).Trim() -ne "651ee13c8edfbdd91cb28f34234fcfb610b53df2") { throw "candidate moved" }

git checkout work/content-search
if ($LASTEXITCODE -ne 0) { throw "checkout candidate failed" }
git merge --ff-only origin/work/content-search
if ($LASTEXITCODE -ne 0) { throw "candidate fast-forward failed" }

if (-not (Test-Path "out\winui\Release\flyExplorer.exe")) { throw "validated candidate Release binary missing" }
if (-not (Test-Path "logs\remote-evidence\content-search-before.png")) { throw "baseline screenshot missing" }
if (-not (Test-Path "logs\capture-content-visual.py")) { throw "content visual helper missing" }

python -X utf8 "logs\capture-content-visual.py" "logs\remote-evidence\content-search-after.png" content
if ($LASTEXITCODE -ne 0) { throw "candidate visual capture failed" }

git diff --check origin/main..HEAD
if ($LASTEXITCODE -ne 0) { throw "diff check failed" }

@"
feature=bounded-content-search
main=28b60642923cf3280f04b43c2322f50eea3b07b1
candidate=651ee13c8edfbdd91cb28f34234fcfb610b53df2
source_contract_run=37172317827
native_build_gui_run=37172446492
"@ | Set-Content -Encoding UTF8 "logs\remote-evidence\manifest.txt"
Write-Host "CONTENT_SEARCH_VISUAL_AND_DIFF_PASS"
